import { lazy, Suspense, type ReactNode } from "react";

export type ThemeName = "nexuswst";

export const themeNames: ThemeName[] = ["nexuswst"];

export type KcEnvName = "NEXUS_MAIL_FROM";

export const kcEnvNames: KcEnvName[] = ["NEXUS_MAIL_FROM"];

